### **8. `piecesMetadata` in [compose/js/index.ts](compose/js/index.ts#L14257)**

**Implementation:**

```typescript
export const piecesMetadata = (kit: Kit, designGuid: string): OperationResult<Map<string, PiecePlacementMetadata>> => {
  const design = findDesignInKit(kit, designGuid);
  if (!design) return operationErr([...]);
  const flattenChange = flattenDesign(kit, designGuid);
  if (!flattenChange.ok) return { ok: false, errors: flattenChange.errors };
  const flatDesign = applyDesignDiff(design, flattenChange.change.forward);
  const fixedPieceIds = flatDesign.pieces?.map((p) => findAttributeValue(p, "compose.fixedPieceId", p.guid) || p.guid);
  const parentPieceIds = flatDesign.pieces?.map((p) => findAttributeValue(p, "compose.parentPieceId", null));
  const depths = flatDesign.pieces?.map((p) => parseInt(findAttributeValue(p, "compose.depth", "0")!));
  const paths = flatDesign.pieces?.map((p) => {
    const raw = findAttributeValue(p, "compose.path", p.guid);
    return raw ? raw.split(",").filter(Boolean) : [p.guid!];
  });
  return operationOk(
    new Map(
      flatDesign.pieces?.map((p, index) => [
        p.guid,
        {
          plane: p.plane!,
          center: p.center!,
          fixedPieceId: fixedPieceIds![index],
          parentPieceId: parentPieceIds![index],
          depth: depths![index],
          path: paths![index],
        },
      ]),
    ),
    flattenChange.warnings,
    flattenChange.infos,
  );
};
```

**Returns Map with:**
- `plane` - World-space transformation matrix
- `center` - World-space center (u, v)
- `fixedPieceId` - Root piece in document
- `parentPieceId` - Parent piece GUID
- `depth` - Distance from root
- `path` - Chain of piece GUIDs from root

